// pxl-kernel/shell/setting/schema.spec.rs
//
// GENERATED by pxl-tool/bin/spec.rs from schema.json — do not edit.
//
// Every setting the app has, declared once: its default, its kind, and
// where the settings sheet shows it. The store reads the defaults from here
// and the sheet renders rows from here, so adding a setting is one entry in
// SETTINGS plus its two strings in the locale catalog under
// `settings.<section>.<key>`. A choice may carry `costs` beside its
// `options`, one per option in the same order, for when what an option costs
// differs from its neighbors'; an empty string is no badge. A `dev` setting
// is in the kernel's table in every build and offered only under a
// development one; the shell's production bundle carries SETTINGS_SHIPPED,
// the table without them, in SETTINGS' place.
//
// A choice's `options` names one of the lists below, and the option crosses
// and is held as its index there; only storage keeps it by name. A setting
// is numbered by its place in SETTINGS (the kernel's SettingKey), which is
// what crosses for it. An `index` is a place in a list kept elsewhere — the
// person and the pet are by theirs in variant.json — and crosses as itself.
// `sources_chunks` marks one a chunk's build reads, so that changing it
// builds the chunks again.

// Casing here is the spec's and not Rust's: a name is spelled as the JSON
// spells it, so that one record is indexed by one name on both sides. To
// case them the way Rust would is to rename the protocol.
#![allow(non_camel_case_types)]

/// Which controller makes the camera's pose.
///
///   orbit — third person: the camera turns about the map center, its
///           radius ahead of the eye, and a drag moves the map center.
///   free  — first person: the eye is the map center and turns in place;
///           a drag walks it as the orbit's center walks, the eye at its
///           height over where the walk stands.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u32)]
pub enum CameraMode {
    orbit = 0,
    free = 1,
}

impl CameraMode {
    pub const ALL: [CameraMode; 2] = [CameraMode::orbit, CameraMode::free];

    /// The option an index names, or none for an index past the list.
    pub fn of(index: u32) -> Option<CameraMode> {
        CameraMode::ALL.get(index as usize).copied()
    }
}

/// Where the ambient occlusion comes from.
///
///   off    — none.
///   corner — a chunk shades its own corners from the face bits the edge
///            shading reads (crates/pxl/web/render/src/frame/shader/chunk.wgsl):
///            the floor along a cube and the inside of a corner, over about
///            half a cell, scaling the ambient and hemisphere light only.
///            A few fragment ops behind a uniform.
///   screen — N8AO
///            (crates/pxl/web/render/src/gpu/ao.rs): the world's depth drawn
///            once more, the occlusion sampled from it at half resolution,
///            denoised, and applied to every lit surface as a warm dark
///            tint. Five passes and 11 bytes a pixel.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u32)]
pub enum AoMode {
    off = 0,
    corner = 1,
    screen = 2,
}

impl AoMode {
    pub const ALL: [AoMode; 3] = [AoMode::off, AoMode::corner, AoMode::screen];

    /// The option an index names, or none for an index past the list.
    pub fn of(index: u32) -> Option<AoMode> {
        AoMode::ALL.get(index as usize).copied()
    }
}

/// How many device pixels the world is drawn at to a CSS pixel.
///
///   auto  — the device's, at most two, lowered while the frames run over
///           their budget — the display's interval, no tighter than a
///           sixtieth of a second — and raised again once they have room
///           (crates/pxl/web/kernel/src/world/frame/resolution.rs).
///   fixed — the device's, at most two, whatever the frames cost.
///   low   — one.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u32)]
pub enum ResolutionMode {
    auto = 0,
    fixed = 1,
    low = 2,
}

impl ResolutionMode {
    pub const ALL: [ResolutionMode; 3] = [ResolutionMode::auto, ResolutionMode::fixed, ResolutionMode::low];

    /// The option an index names, or none for an index past the list.
    pub fn of(index: u32) -> Option<ResolutionMode> {
        ResolutionMode::ALL.get(index as usize).copied()
    }
}

/// How a setting is held.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SettingKind {
    Toggle,
    Choice,
    Index,
}

/// Every setting, by its place in schema.json's SETTINGS.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u32)]
pub enum SettingKey {
    /// Ground color from the art pack (four taps of the layer array per
    /// fragment) instead of the flat per-instance average. The chunk shader's
    /// `frame.low_spec` is this, inverted.
    ///
    /// Low because the four taps are all of it: fill rate, which scales with
    /// the screen and not with the world, and nothing else — no geometry, no
    /// pass of its own, and no work off the GPU past an atlas the client
    /// already holds.
    ///
    /// It sources the chunks: the shader samples a leaf's layer or does not,
    /// but a tier over it carries one color and no layer to sample, so which
    /// color that is was baked in (mesh/chunk_mesher.rs).
    textures = 0,
    /// Whether the STRUCTURE ground channel is painted. The bake writes it
    /// either way (pxl-geo-bake terrain/pipeline/overture/policy.rs); this is a render decision.
    structures = 1,
    /// Procedurally scattered decor only; what the player placed stays.
    ///
    /// Med because it is models rather than a shading term: a chunk builds its
    /// decor and the frame draws it, so what it costs follows what is in view.
    /// It has been the frame's own bottleneck — 20260912-what-to-render-when.md
    /// reads GPU p95 24.1 ms with 2.26 M decor triangles and 15% of moving
    /// frames missing a vsync — and the projected-size criterion holds it to
    /// the nearest tier without making far decor cheap, the impostor tier that
    /// would being decided and not built. The badge is an ordering, and this is
    /// the one to reach for before any shading term.
    decor = 2,
    /// The places' badges over the map, from the published POI pages.
    poi = 3,
    /// Rotate-drag and pinch stop writing polar; azimuth is unaffected.
    /// Off by default: the tilt is the one control a map view is expected to
    /// have, and locking it reads as the app being stuck.
    tilt_lock = 4,
    /// Which controller makes the camera's pose; CAMERA_MODES says each. To
    /// first person the person stands at the map center, the eye at its
    /// height over the ground; to third the map center is laid on the ground
    /// and the eye steps back by the radius.
    camera_mode = 5,
    /// Darkens cube edges that border open air (crates/pxl/web/render/src/frame/shader/chunk.wgsl).
    /// A few fragment ops behind a uniform; the shader is the same either way.
    edge_shade = 6,
    /// A uniform on an already-compiled shader term; not a pass.
    rim_light = 7,
    /// corner, the occlusion a voxel world gets from its own geometry with no
    /// screen-space pass; screen, N8AO's screen-space pass, the costliest of
    /// the three. AO_MODES says each.
    ao = 8,
    /// The sun's shadow map (crates/pxl/web/render/src/gpu/shadow.rs): the world drawn once more
    /// from the sun each frame, depth only, and a 3x3 compare per fragment;
    /// 16 MB of map on a desktop, 4 on a phone.
    shadows = 9,
    /// The pixels the world is filled at, the GPU's largest cost: two to a
    /// CSS pixel is four times the fragments of one. RESOLUTION_MODES says each.
    resolution = 10,
    /// The performance overlay: the profiler's panel, and the profiler recording while it is on (sched/profiler/log.rs `profiler_follow`).
    profiler = 11,
    /// Markers for the map center and the cell it floors to, the floating origin, the page's corners and the two gyro rings (layer/marker/frame_gizmo.rs).
    gizmos = 12,
    person = 13,
    pet = 14,
}

impl SettingKey {
    pub const ALL: [SettingKey; 15] = [
        SettingKey::textures,
        SettingKey::structures,
        SettingKey::decor,
        SettingKey::poi,
        SettingKey::tilt_lock,
        SettingKey::camera_mode,
        SettingKey::edge_shade,
        SettingKey::rim_light,
        SettingKey::ao,
        SettingKey::shadows,
        SettingKey::resolution,
        SettingKey::profiler,
        SettingKey::gizmos,
        SettingKey::person,
        SettingKey::pet,
    ];

    /// The setting a number names, or none for a number past the table.
    pub fn of(number: u32) -> Option<SettingKey> {
        SettingKey::ALL.get(number as usize).copied()
    }

    pub fn kind(self) -> SettingKind {
        match self {
            SettingKey::textures => SettingKind::Toggle,
            SettingKey::structures => SettingKind::Toggle,
            SettingKey::decor => SettingKind::Toggle,
            SettingKey::poi => SettingKind::Toggle,
            SettingKey::tilt_lock => SettingKind::Toggle,
            SettingKey::camera_mode => SettingKind::Choice,
            SettingKey::edge_shade => SettingKind::Toggle,
            SettingKey::rim_light => SettingKind::Toggle,
            SettingKey::ao => SettingKind::Choice,
            SettingKey::shadows => SettingKind::Toggle,
            SettingKey::resolution => SettingKind::Choice,
            SettingKey::profiler => SettingKind::Toggle,
            SettingKey::gizmos => SettingKind::Toggle,
            SettingKey::person => SettingKind::Index,
            SettingKey::pet => SettingKind::Index,
        }
    }

    /// Its name, as storage keeps it.
    pub fn name(self) -> &'static str {
        match self {
            SettingKey::textures => "textures",
            SettingKey::structures => "structures",
            SettingKey::decor => "decor",
            SettingKey::poi => "poi",
            SettingKey::tilt_lock => "tilt_lock",
            SettingKey::camera_mode => "camera_mode",
            SettingKey::edge_shade => "edge_shade",
            SettingKey::rim_light => "rim_light",
            SettingKey::ao => "ao",
            SettingKey::shadows => "shadows",
            SettingKey::resolution => "resolution",
            SettingKey::profiler => "profiler",
            SettingKey::gizmos => "gizmos",
            SettingKey::person => "person",
            SettingKey::pet => "pet",
        }
    }

    /// A choice's options by name, in index order; none for any other kind.
    pub fn options(self) -> &'static [&'static str] {
        match self {
            SettingKey::camera_mode => &["orbit", "free"],
            SettingKey::ao => &["off", "corner", "screen"],
            SettingKey::resolution => &["auto", "fixed", "low"],
            _ => &[],
        }
    }

    /// Offered by a development build only.
    pub fn dev(self) -> bool {
        matches!(self, SettingKey::shadows)
    }

    /// Read by a chunk's build, so a change builds the chunks again.
    pub fn sources_chunks(self) -> bool {
        matches!(self, SettingKey::textures | SettingKey::structures | SettingKey::decor)
    }
}

/// Every setting's value: what the store holds, and what the app reads.
#[derive(Clone, Debug, PartialEq)]
pub struct Settings {
    pub textures: bool,
    pub structures: bool,
    pub decor: bool,
    pub poi: bool,
    pub tilt_lock: bool,
    pub camera_mode: CameraMode,
    pub edge_shade: bool,
    pub rim_light: bool,
    pub ao: AoMode,
    pub shadows: bool,
    pub resolution: ResolutionMode,
    pub profiler: bool,
    pub gizmos: bool,
    pub person: u8,
    pub pet: u8,
}

impl Settings {
    /// Every setting at schema.json's default.
    pub const DEFAULT: Settings = Settings {
        textures: true,
        structures: true,
        decor: true,
        poi: false,
        tilt_lock: false,
        camera_mode: CameraMode::orbit,
        edge_shade: true,
        rim_light: true,
        ao: AoMode::corner,
        shadows: false,
        resolution: ResolutionMode::auto,
        profiler: false,
        gizmos: false,
        person: 1,
        pet: 5,
    };

    /// A setting's value as it crosses: a toggle's 0 or 1, a choice's option
    /// by its place in its list, an index as itself.
    pub fn get(&self, key: SettingKey) -> u32 {
        match key {
            SettingKey::textures => self.textures as u32,
            SettingKey::structures => self.structures as u32,
            SettingKey::decor => self.decor as u32,
            SettingKey::poi => self.poi as u32,
            SettingKey::tilt_lock => self.tilt_lock as u32,
            SettingKey::camera_mode => self.camera_mode as u32,
            SettingKey::edge_shade => self.edge_shade as u32,
            SettingKey::rim_light => self.rim_light as u32,
            SettingKey::ao => self.ao as u32,
            SettingKey::shadows => self.shadows as u32,
            SettingKey::resolution => self.resolution as u32,
            SettingKey::profiler => self.profiler as u32,
            SettingKey::gizmos => self.gizmos as u32,
            SettingKey::person => self.person as u32,
            SettingKey::pet => self.pet as u32,
        }
    }

    /// Sets a setting from its value as it crosses; false, and nothing set,
    /// for a value the setting cannot hold.
    pub fn set(&mut self, key: SettingKey, value: u32) -> bool {
        match key {
            SettingKey::textures if value <= 1 => self.textures = value == 1,
            SettingKey::structures if value <= 1 => self.structures = value == 1,
            SettingKey::decor if value <= 1 => self.decor = value == 1,
            SettingKey::poi if value <= 1 => self.poi = value == 1,
            SettingKey::tilt_lock if value <= 1 => self.tilt_lock = value == 1,
            SettingKey::camera_mode => match CameraMode::of(value) {
                Some(o) => self.camera_mode = o,
                None => return false,
            },
            SettingKey::edge_shade if value <= 1 => self.edge_shade = value == 1,
            SettingKey::rim_light if value <= 1 => self.rim_light = value == 1,
            SettingKey::ao => match AoMode::of(value) {
                Some(o) => self.ao = o,
                None => return false,
            },
            SettingKey::shadows if value <= 1 => self.shadows = value == 1,
            SettingKey::resolution => match ResolutionMode::of(value) {
                Some(o) => self.resolution = o,
                None => return false,
            },
            SettingKey::profiler if value <= 1 => self.profiler = value == 1,
            SettingKey::gizmos if value <= 1 => self.gizmos = value == 1,
            SettingKey::person => match u8::try_from(value) {
                Ok(n) => self.person = n,
                Err(_) => return false,
            },
            SettingKey::pet => match u8::try_from(value) {
                Ok(n) => self.pet = n,
                Err(_) => return false,
            },
            _ => return false,
        }
        true
    }
}
